-- ── 1 · One named instance, stated by the definition. ───────────────────────
-- evaluate_cardinality had six kinds and none of them said "exactly one, and it is
-- called this". A Turner pass belongs to pile 4 and to no other; PER_SCOPE_INSTANCE
-- would put all six piles on one hour, and SINGLETON would label it "Whole batch".
-- The label is data in the rule, so no count and no pile name enters any code path.

-- The six original kinds move aside under their own name rather than being retyped here.
-- Retyping them is how a rule that has been correct since 0005 acquires a difference.
do $$
begin
  if not exists (
    select 1 from pg_proc p join pg_namespace n on n.oid = p.pronamespace
     where n.nspname = 'public' and p.proname = 'evaluate_cardinality_v1') then
    alter function public.evaluate_cardinality(jsonb, jsonb) rename to evaluate_cardinality_v1;
  end if;
end $$;

create or replace function public.evaluate_cardinality(
  p_rule jsonb, p_config jsonb
) returns table (instance_no int, scope_label text, planned_qty_mt numeric)
language plpgsql stable as $fn$
begin
  if p_rule->>'kind' = 'FIXED_LABEL' then
    if coalesce(p_rule->>'label', '') = '' then
      raise exception 'A FIXED_LABEL cardinality rule must carry a label.';
    end if;
    return query select 1, p_rule->>'label', null::numeric;
    return;
  end if;
  return query select * from public.evaluate_cardinality_v1(p_rule, p_config);
end;
$fn$;

comment on function public.evaluate_cardinality(jsonb, jsonb) is
  'Seven rule kinds. FIXED_LABEL (0043) is one instance carrying a label the definition
  states — a Turner pile-pass, a bunker line, a tunnel stream. Everything else delegates
  to evaluate_cardinality_v1, which is 0005 unchanged.';


-- ── 2 · A hold is not a task. ──────────────────────────────────────────────
-- Six of the fifteen rail activities and both bunker conditionings are HOLD: material
-- resting, nobody working. 128 of the first 174 hours are holds. Without this column
-- the operator's queue offers a 63-hour bunker conditioning as something to press
-- START on, and the two kinds become indistinguishable the moment they are planned.

alter table public.process_activity add column if not exists is_hold boolean not null default false;
alter table public.batch_activity   add column if not exists is_hold boolean not null default false;

comment on column public.process_activity.is_hold is
  'true = material is resting and no one is working. STANDARD.md KIND = HOLD. 0043.';


