-- The envelope is a factory statement, not (total_days + 1) × 24. 0041 / F7.
-- 470 is not a multiple of 24 and baseline_hours physically cannot hold it.
update public.process_definition
   set envelope_hours       = 470,
       envelope_hour_source = 'factory_stated',
       envelope_confidence  = 'FACTORY_CONFIRMED'
 where code = 'PROCESS-2026C' and version = 1;

-- Days exist so the calendar screens have a title per rel_day. The day grid is not the
-- envelope — 0041 §2 — it is a label.
with pd as (select id from public.process_definition where code = 'PROCESS-2026C' and version = 1)
insert into public.process_day (process_definition_id, rel_day, title, source_ref)
select pd.id, d, 'Day ' || d, 'docs/01-process/schedule.json · PROCESS-2026C v1, confirmed 30 Aug 2026' from pd, generate_series(0, 19) d
on conflict (process_definition_id, rel_day) do update set title = excluded.title;


