  ('TN-COOL-1', 'Cooling down 1', null, 'TUNNEL', 15, 640, 'TUNNEL', '{"kind":"SINGLETON"}', 12, 14, 364.5, 377.5, true, 'operator', null, 'FACTORY_RANGE', null::text[]),
  ('TN-COND-2', 'Conditioning 2', null, 'TUNNEL', 15, 650, 'TUNNEL', '{"kind":"SINGLETON"}', 80, 85, 377.5, 459, true, 'operator', null, 'FACTORY_RANGE', null::text[]),
  ('TN-COOL-2', 'Cooling down 2', null, 'TUNNEL', 19, 660, 'TUNNEL', '{"kind":"SINGLETON"}', 8, 14, 459, 470, true, 'operator', null, 'FACTORY_RANGE', null::text[]),
  ('TUN-DISCHARGE-1', 'Tunnel discharge to grow-room — stream 1', null, 'TUNNEL', 19, 670, 'TUNNEL', '{"kind":"FIXED_LABEL","label":"Stream 1"}', null, null, 470, null, false, 'operator', 'H470 is the standard end, and it is measured on stream 1.', 'FACTORY_CONFIRMED', null::text[]),
  ('TUN-DISCHARGE-2', 'Tunnel discharge to grow-room — stream 2', null, 'TUNNEL', 19, 680, 'TUNNEL', '{"kind":"FIXED_LABEL","label":"Stream 2"}', null, null, 472, null, false, 'operator', null, 'FACTORY_CONFIRMED', null::text[]),
  ('TUN-DISCHARGE-3', 'Tunnel discharge to grow-room — stream 3', null, 'TUNNEL', 19, 690, 'TUNNEL', '{"kind":"FIXED_LABEL","label":"Stream 3"}', null, null, 474, null, false, 'operator', null, 'FACTORY_CONFIRMED', null::text[])
) as a(code, label, material_role, stream, rel_day, seq, scope, cardinality, dmin, dmax,
       hstart, hend, is_hold, role, golden, confidence, lab_params)
on conflict (process_definition_id, code) do update set
  label_template = excluded.label_template,
  material_role  = excluded.material_role,
  stream         = excluded.stream,
  rel_day        = excluded.rel_day,
  seq            = excluded.seq,
  scope          = excluded.scope,
  cardinality_rule = excluded.cardinality_rule,
  duration_target_min_hr = excluded.duration_target_min_hr,
  duration_target_max_hr = excluded.duration_target_max_hr,
  standard_start_hour  = excluded.standard_start_hour,
  standard_end_hour    = excluded.standard_end_hour,
  standard_hour_source = excluded.standard_hour_source,
  is_hold          = excluded.is_hold,
  responsible_role = excluded.responsible_role,
  golden_rule      = excluded.golden_rule,
  timing_confidence = excluded.timing_confidence,
  lab_parameters   = excluded.lab_parameters;


-- ── 5 · Two photographs on every activity someone actually performs. ───────
-- Master PRD: BEFORE / START and AFTER / FINISH. A hold has nobody to photograph it,
-- so holds are excluded — which is also why is_hold exists.

with pa as (
  select pa.id from public.process_activity pa
  join public.process_definition pd on pd.id = pa.process_definition_id
  where pd.code = 'PROCESS-2026C' and pd.version = 1
    and not pa.is_hold
    -- ⚠ AND NOT A LABORATORY ACTIVITY. 0053 adds 41 of them to this same definition,
    -- and on a REPLAY they already exist when this statement runs — so 'every non-hold
    -- activity' silently gave a moisture reading a BEFORE and an AFTER photograph on top
    -- of the SAMPLE_PHOTO its checkpoint actually asks for. Laboratory evidence is
    -- checkpoint-specific and 0053 is the only thing that may seed it.
    and pa.responsible_role <> 'lab_tech')
insert into public.evidence_requirement
  (process_activity_id, key, label, media_kinds, min_count, is_required, gates_submission,
   capture_hint, ordering)
select pa.id, r.key, r.label, array['photo']::text[], 1, true, true, r.hint, r.ord
from pa, (values
  ('BEFORE_PHOTO', 'Before starting', 'Photograph the material and the position before you begin.', 10),
  ('AFTER_PHOTO',  'After finishing', 'Photograph the result before you finish the task.', 20)
) as r(key, label, hint, ord)
on conflict do nothing;


-- ── 6 · The gate the Turner actually has. ──────────────────────────────────
-- Eight hours from THAT pile's own T1 ACTUAL end (F10). It is a condition on an actual,
-- so it is a gate rule and never a planned hour. T2 = T0 start + 24 h was rejected on
-- 30 Aug and must not be built.

with pd as (select id from public.process_definition where code = 'PROCESS-2026C' and version = 1)
insert into public.gate_rule
  (process_activity_id, phase, kind, config, predecessor_binding, is_enabled,
   mapping_confidence, blocked_reason_template, ordering)
select t2.id, 'entry', 'PREDECESSOR',
       jsonb_build_object('activity_codes', jsonb_build_array(t1.code), 'min_rest_hr', 8),
       'SAME_SCOPE_INSTANCE', true, 'dictated',
       'Locked — {predecessor_label} finished less than 8 hours ago. This pile''s T2 is eligible 8 hours after its own T1 actual end.',
       10
from pd
join public.process_activity t2 on t2.process_definition_id = pd.id and t2.code like 'TRN-P%-T2'
join public.process_activity t1 on t1.process_definition_id = pd.id
  and t1.code = replace(t2.code, '-T2', '-T1')
where not exists (
  select 1 from public.gate_rule g
   where g.process_activity_id = t2.id and g.phase = 'entry' and g.kind = 'PREDECESSOR');

